const { itemTypeName, getState } = options
const isInBasket = itemTypeName === 'InBasket Task';

if (isInBasket) {
	return {hidden: !target.children, disabled: false};
}
const state = getState();
const disabled = state.grid.selectedRows.every(
	rowId => ArasModules.item.isNew(itemTypeName, rowId)
);
return { disabled };
